909 :                             // insert a split
910 :                             work[i + 2]  = -sigma;
911 :                             split        = i / 4;
912 :                             diagMax      = 0;
913 :                             offDiagMin   = work[i + 6];
914 :                             previousEMin = work[i + 7];
